<script setup lang="ts">
import {locale,tr} from '../lib/i18n'
import { computed, ref, onMounted, onUnmounted, watch } from 'vue'
import ProfileFlow from './ProfileFlow.vue'
import ReplyTopup from './ReplyTopup.vue'
import InboxFlow from './InboxFlow.vue'
import LettersFlow, { type Letter } from './LettersFlow.vue'
import { api, ApiError } from '../lib/api'
import { asset } from '../lib/assets'
const props=defineProps<{token:string;userId:string}>()
const emit=defineEmits<{signin:[];security:[]}>()
type Pass={active:boolean;expiresAt:string|null;remainingDays:number;plans:{days:number;diamonds:number}[]}
const sheet=ref(''),error=ref(''),busy=ref(false),items=ref<Letter[]>([]),responses=ref<{openingMessageId:string}[]>([]),detail=ref<Letter>(),loaded=ref(false)
const pass=ref<Pass>({active:false,expiresAt:null,remainingDays:0,plans:[]}), now=ref(Date.now()),cities=ref<string[]>([])
const letterOrigin=ref({'--letter-x':'0px','--letter-y':'0px'})
const walletOpen=ref(false),passPage=ref(false)
const passBalance=ref(0),passTopup=ref(false),passNotice=ref('')
const selectedPlan=ref<Pass['plans'][number]>(),purchaseKey=ref('')
const validUntil=computed(()=>new Date(Math.max(now.value,new Date(pass.value.expiresAt||0).getTime())+(selectedPlan.value?.days||0)*86400000).toLocaleString(locale.value==='ko'?'ko-KR':'en-US'))
const active=computed(()=>pass.value.active&&!!pass.value.expiresAt&&new Date(pass.value.expiresAt).getTime()>now.value)
const days=computed(()=>active.value?Math.ceil((new Date(pass.value.expiresAt!).getTime()-now.value)/86400000):0)
const savedFilters=JSON.parse(localStorage.getItem('maugo-discovery-filters')||'{}')
const gender=ref<string>(savedFilters.gender||''),city=ref<string>(savedFilters.city||''),min=ref<number>(savedFilters.min??18),max=ref<number>(savedFilters.max??50),ageSet=ref<boolean>(savedFilters.ageSet??false)
watch([gender,city,min,max,ageSet],()=>localStorage.setItem('maugo-discovery-filters',JSON.stringify({gender:gender.value,city:city.value,min:min.value,max:max.value,ageSet:ageSet.value})),{flush:'sync'})
const filters=computed(()=>({...(gender.value?{gender:gender.value}:{}),...(active.value&&city.value?{city:city.value}:{}),...(active.value&&ageSet.value?{minAge:min.value,...(max.value<50?{maxAge:max.value}:{})}:{})}))
const changingComposeBird=ref(false)
const previewRun=ref(0)
const birdGender=ref('female'),variant=ref(1),motion=ref(true),trails=ref(true)
try{const p=JSON.parse(localStorage.getItem('maugo-bird')||'{}');if(['male','female'].includes(p.gender))birdGender.value=p.gender;if(Number.isInteger(p.variant)&&p.variant>=1&&p.variant<=9)variant.value=p.variant;motion.value=p.motion!==false;trails.value=p.trails!==false}catch{}
watch([birdGender,variant,motion,trails],()=>localStorage.setItem('maugo-bird',JSON.stringify({gender:birdGender.value,variant:variant.value,motion:motion.value,trails:trails.value})))
const variants=['Sky blue','Sunshine','Sage green','Soft lilac','Fresh mint','Sunset peach','Blueberry blush','Pastel rainbow','Aurora']
const bird=computed(()=>asset(`02-bird-static/${birdGender.value}-${variant.value}`))
const flight=computed(()=>asset(`03-bird-flight-sheets/${birdGender.value}-${variant.value}-fly`))
const headers=()=>({Authorization:`Bearer ${props.token}`})
async function request<T>(path:string,body?:object,extra?:Record<string,string>){return api<T>(path,{method:body?'POST':'GET',headers:{...headers(),...(body?{'Content-Type':'application/json'}:{}),...extra},...(body?{body:JSON.stringify(body)}:{})})}
async function status(){const [p,f]=await Promise.all([request<Pass>('/filter-pass'),request<{cities:string[]}>('/discovery/filters')]);pass.value=p;cities.value=f.cities;now.value=Date.now()}
async function load(refresh=false){if(busy.value)return;if(!props.token){error.value='Sign in to meet your letters.';return}busy.value=true;error.value='';try{await status();const discoveryFilters=JSON.parse(localStorage.getItem('maugo-settings')||'{}').recommendations===false?{}:filters.value;const data=await request<{items:Letter[];responses:{openingMessageId:string}[];locked?:boolean}>(refresh?'/letters/refresh':`/letters?${new URLSearchParams(Object.entries(discoveryFilters).map(([k,v])=>[k,String(v)]))}`,refresh?discoveryFilters:undefined);if(data.locked){pass.value.active=false;city.value='';ageSet.value=false;throw new Error('Your Filter Pass has expired. Please try again.')}items.value=data.items;responses.value=data.responses||[];loaded.value=true}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function openLetter(id:string,event:MouseEvent){const source=(event.currentTarget as HTMLElement).getBoundingClientRect(),home=(event.currentTarget as HTMLElement).closest('.home-flow')!.getBoundingClientRect();letterOrigin.value={'--letter-x':`${source.left+source.width/2-home.left-home.width/2}px`,'--letter-y':`${source.top+source.height/2-home.top-202}px`};error.value='';try{detail.value=await request<Letter>(`/letters/${id}`);responses.value=responses.value.filter(r=>r.openingMessageId!==id);sheet.value='letter'}catch(e){error.value=(e as Error).message}}
async function openFilters(){sheet.value='filters';if(props.token)try{await status();passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds}catch(e){error.value=(e as Error).message}}
async function openPass(){error.value='';passNotice.value='';try{await status();passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds;selectedPlan.value=pass.value.plans.find(p=>p.days===7);sheet.value='pass-page'}catch(e){error.value=(e as Error).message}}
async function confirmPlan(plan:Pass['plans'][number]){if(busy.value)return;passPage.value=sheet.value==='pass-page';if(selectedPlan.value?.days!==plan.days||!purchaseKey.value)purchaseKey.value=crypto.randomUUID();selectedPlan.value=plan;error.value='';passNotice.value='';busy.value=true;try{passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds;sheet.value='pass-confirm'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function closeSheet(){if(changingComposeBird.value){changingComposeBird.value=false;sheet.value='compose';return}if(busy.value&&sheet.value==='pass-confirm')return;if(sheet.value==='pass-page'){sheet.value='';return}if(['pass','pass-confirm','pass-success'].includes(sheet.value)){error.value='';sheet.value='filters'}else sheet.value=''}
async function returnToPass(funded=false){passTopup.value=false;sheet.value='pass-confirm';passNotice.value=funded?'Diamonds added. Confirm your selected Pass to continue.':'Top-up closed. No Pass purchased; selection saved.';try{passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds}catch(e){error.value=(e as Error).message}}
async function purchase(days:number){if(busy.value)return;busy.value=true;error.value='';try{pass.value={...pass.value,...await request<Pass>('/filter-pass/purchase',{days},{'Idempotency-Key':purchaseKey.value})};const [wallet,confirmed]=await Promise.all([request<{diamonds:number}>('/wallet'),request<Pass>('/filter-pass')]);passBalance.value=wallet.diamonds;pass.value=confirmed;purchaseKey.value='';passNotice.value=`Filter Pass unlocked for ${days} days.`;sheet.value=passPage.value?'pass-success':'filters'}catch(e){if(e instanceof ApiError&&e.status===402){passBalance.value=(await request<{diamonds:number}>('/wallet')).diamonds;passNotice.value='Not enough diamonds. Add diamonds to continue.'}else error.value=(e as Error).message}finally{busy.value=false}}
watch(active,(value,old)=>{if(old&&!value){city.value='';ageSet.value=false;min.value=18;max.value=50;if(!busy.value)void load()}})
const tick=setInterval(()=>{now.value=Date.now()},500)
function escape(e:KeyboardEvent){if(e.key==='Escape'&&!passTopup.value&&!['letter','compose','inbox'].includes(sheet.value))closeSheet()}
onMounted(()=>{void load();document.addEventListener('keydown',escape)})
onUnmounted(()=>{clearInterval(tick);document.removeEventListener('keydown',escape)})
</script>
<template>
<Transition name="tab-page">
<InboxFlow v-if="sheet==='inbox'" :token="token" :user-id="userId" @close="sheet=''" @profile="sheet='profile'" @signin="emit('signin')" />
<ProfileFlow v-else-if="sheet==='profile'" :token="token" @close="sheet=''" @inbox="sheet='inbox'" @security="emit('security')" />
<section v-else class="home-flow" :class="{'motion-off':!motion,'refreshing':busy}" :data-state="responses.length?'home-response':items.length?'home-ready':'home-empty'">
<header class="home-header"><img :src="asset('01-brand-scenes/maugo-wordmark')" :alt="tr('MauGo')"><div><button id="magic" :aria-label="tr('Bird appearance')" @click="sheet='appearance'"><img :src="asset('11-symbol-icons/icon-bird-appearance-light-25')" alt=""></button><button id="settings" :aria-label="tr('Filters')" @click="openFilters"><img :src="asset('08-interface-icons/icon-filter-light-25')" alt=""></button></div></header>
<div v-if="error&&sheet!=='pass-confirm'" class="home-error" role="alert">{{tr(error)}} <button v-if="!token" @click="emit('signin')">{{tr("Sign in")}}</button><button v-else :disabled="busy" @click="load()">{{tr("Retry")}}</button></div>
<div v-if="responses.length" class="response-strip"><button v-for="r in responses" :key="r.openingMessageId" @click="openLetter(r.openingMessageId,$event)">{{tr("✉ Replied to you")}} <small>{{tr("Tap to open")}}</small></button></div>
<section class="magic-scene" :aria-busy="busy"><div class="aura"></div><img class="scene-mist" :src="asset('01-brand-scenes/mist')" alt=""><svg v-if="trails" class="magic-trails" viewBox="0 0 375 812" aria-hidden="true"><defs><filter id="home-trail-glow"><feGaussianBlur stdDeviation="3"/></filter></defs><g class="trail-blur"><path d="M188 448 C185 388 99 385 91 340"/><path d="M188 448 C199 376 146 335 190 264"/><path d="M188 448 C191 402 252 385 280 345"/></g><g><path d="M188 448 C185 388 99 385 91 340"/><path d="M188 448 C199 376 146 335 190 264"/><path d="M188 448 C191 402 252 385 280 345"/></g></svg><span v-if="trails" class="magic-sparks">✦ · ✧ · ✦</span>
<TransitionGroup name="birds" tag="div" class="bird-layer"><button v-for="(letter,i) in items" :key="letter.openingMessageId" class="letter-bird" :style="{'--i':i}" :aria-label="`Open letter from ${letter.sender.displayName}`" @click="openLetter(letter.openingMessageId,$event)"><span v-if="motion" :key="previewRun" class="flight-sprite" :style="{backgroundImage:`url(${flight})`}"></span><img v-else :src="bird" alt=""><small>{{letter.sender.displayName}}</small></button></TransitionGroup>
<button id="hat" class="magic-hat" :aria-label="tr('Tap the hat to meet three new letters')" :disabled="busy" @click="load(true)"><img :src="asset('01-brand-scenes/hat')" :alt="tr('A black magic hat with a glowing green ribbon')"></button>
</section>
<p class="scene-hint">{{tr(busy?'Your little birds are on their way…':loaded&&!items.length?'No letters match just yet. Try another little wish.':'Tap a bird. Open a little story.')}}</p>
<div class="economy-actions"><button id="open-wallet" @click="walletOpen=true"><img :src="asset('01-brand-scenes/diamond')" alt="">{{tr("Diamonds")}}</button><button id="open-pass" @click="openPass">{{tr("Filter Pass")}} ›</button></div><div class="home-actions"><button id="refresh" :aria-label="tr('Refresh')" :disabled="busy" @click="load(true)"><img :src="asset('08-interface-icons/icon-refresh-light-24')" alt="">{{tr('Refresh')}}</button><button id="compose" class="primary" :aria-label="tr('Write a letter')" @click="sheet='compose'"><img :src="asset('08-interface-icons/icon-send-dark-24')" alt="">{{tr('Send a letter')}}</button></div><nav class="main-nav"><button class="main-nav__item" type="button" aria-current="page"><img :src="asset('09-navigation-system/tab-discover-active')" alt="">{{tr("Home")}}</button><button class="main-nav__item" type="button" id="open-inbox" @click="sheet='inbox'"><img :src="asset('09-navigation-system/tab-messages-inactive')" alt="">{{tr("Messages")}}</button><button class="main-nav__item" type="button" id="open-profile" :aria-label="tr('My profile')" @click="sheet='profile'"><img :src="asset('09-navigation-system/tab-profile-inactive')" alt="">{{tr("Profile")}}</button></nav>
<img v-if="sheet==='letter'" class="d11-flying-letter" :style="letterOrigin" :src="asset('01-brand-scenes/envelope')" alt="" aria-hidden="true">
<Transition name="letter-overlay" :duration="{enter:sheet==='compose'?300:580,leave:440}"><LettersFlow v-if="sheet==='letter'||sheet==='compose'||changingComposeBird" v-show="!changingComposeBird" :key="sheet==='letter'?detail?.openingMessageId:'compose'" :token="token" :letter="sheet==='letter'?detail:undefined" :compose="sheet==='compose'||changingComposeBird" :messenger="bird" :suspended="changingComposeBird" @change-bird="changingComposeBird=true;sheet='appearance'" @close="sheet=''" @blocked="items=items.filter(i=>i.openingMessageId!==$event);responses=responses.filter(i=>i.openingMessageId!==$event)" /></Transition>
<ReplyTopup v-if="walletOpen" :balance="passBalance" :token="token" :user-id="userId" context="Home" @back="walletOpen=false" @funded="walletOpen=false" />
<ReplyTopup v-if="passTopup" :balance="passBalance" :token="token" :user-id="userId" :required="selectedPlan?.diamonds" context="Pass" @back="returnToPass()" @funded="returnToPass(true)" />
<Transition name="sheet"><div v-if="!passTopup&&sheet&&!['letter','compose','inbox'].includes(sheet)" class="home-veil" :class="{'pass-payment-veil':sheet==='pass-confirm'}" @click.self="closeSheet">
<section class="home-sheet" :class="{'pass-payment-dialog':sheet==='pass-confirm','pass-page':sheet==='pass-page'}" role="dialog" aria-modal="true" :data-state="sheet==='filters'?(Object.keys(filters).length?'filters-selected':active?'filters-active':'filters-free'):sheet==='appearance'?(!motion?'bird-motion-off':`bird-${birdGender}`):sheet" :aria-label="tr(sheet==='appearance'?'Choose your bird':sheet==='filters'?'Find your letters':sheet==='pass-confirm'?'Confirm Filter Pass':['pass','pass-page','pass-success'].includes(sheet)?'Filter Pass':'A letter for you')"><header><h2>{{tr(sheet==='appearance'?'Choose your bird':sheet==='filters'?'Find your letters':sheet==='pass-confirm'?'Confirm Filter Pass':['pass','pass-page','pass-success'].includes(sheet)?'Filter Pass':'A letter for you')}}</h2><button :aria-label="tr('Close')" :disabled="busy&&sheet==='pass-confirm'" @click="closeSheet"><img :src="asset('11-symbol-icons/icon-close-24-acbcaa')" alt=""></button></header>
<template v-if="sheet==='filters'"><p>{{tr("Gender")}}</p><div class="gender-options"><button v-for="g in [['male','♂','Man'],['female','♀','Woman'],['','∞','Everyone']]" :key="g[0]" :aria-label="tr(`Filter ${g[2]}`)" :aria-pressed="gender===g[0]" @click="gender=g[0]!"><i>{{tr(g[1])}}</i>{{tr(g[2])}}</button></div><p>{{tr("Age range")}} <button class="pass-badge" @click="sheet='pass';selectedPlan=pass.plans.find(p=>p.days===7)">{{tr("◆ Pass")}}</button><small>{{min}}–{{tr(max===50?'50+':max)}}</small></p><div class="premium-zone"><label>{{tr("Minimum age")}}<input v-model.number="min" :aria-label="tr('Minimum age')" type="range" min="18" max="50" :disabled="!active" @input="ageSet=true;max=Math.max(max,min)"></label><label>{{tr("Maximum age")}}<input v-model.number="max" :aria-label="tr('Maximum age')" type="range" min="18" max="50" :disabled="!active" @input="ageSet=true;min=Math.min(min,max)"></label><button v-if="!active" class="premium-cover" @click="sheet='pass';selectedPlan=pass.plans.find(p=>p.days===7)">{{tr("♢ Unlock age and city filters")}}</button></div><p>{{tr("City")}} <button class="pass-badge" @click="sheet='pass';selectedPlan=pass.plans.find(p=>p.days===7)">{{tr("◆ Pass")}}</button></p><select v-model="city" :aria-label="tr('City')" :disabled="!active"><option value="">{{tr("Any city")}}</option><option v-for="c in cities" :key="c">{{c}}</option></select><small class="city-source">{{tr("City options · temporary data source")}}</small><p class="pass-status">{{tr(active?`Filter Pass · ${days} days remaining`:'Choose a day pass to unlock age and city filters.')}}</p><button v-if="!active" class="unlock-pass" @click="sheet='pass';selectedPlan=pass.plans.find(p=>p.days===7)">{{tr("Unlock Filter Pass")}}</button><button class="primary" :disabled="busy" @click="sheet='';load()">{{tr("Done")}}</button></template>
<template v-else-if="sheet==='appearance'"><div id="appearance-genders" class="gender-options"><button v-for="g in ['male','female']" :key="g" :aria-pressed="birdGender===g" @click="birdGender=g"><img :src="asset(`02-bird-static/${g}-${variant}`)" alt="">{{tr(g==='male'?'Male bird':'Female bird')}}</button></div><div class="appearance-grid"><button v-for="(name,i) in variants" :key="name" :aria-pressed="variant===i+1" :aria-label="tr(`Choose ${name}`)" @click="variant=i+1"><img :src="asset(`02-bird-static/${birdGender}-${i+1}`)" alt=""><span>{{tr(name)}}</span></button></div><div class="flight-preview"><span v-if="motion" :key="previewRun" class="flight-sprite" :style="{backgroundImage:`url(${flight})`}"></span><img v-else :src="bird" alt=""><span>{{tr("Flight preview")}}</span><button type="button" @click="previewRun++">{{tr("Replay")}}</button></div><label class="switch-row">{{tr("Flight & hover")}}<input v-model="motion" type="checkbox"></label><label class="switch-row">{{tr("Magic trails")}}<input v-model="trails" type="checkbox"></label><button class="primary" @click="closeSheet">{{tr("Done")}}</button></template>
<template v-else-if="sheet==='pass'||sheet==='pass-page'"><div class="filter-pass-intro"><img :src="asset('08-interface-icons/icon-filter-lime-32')" alt=""><h3>{{tr("More ways to browse letters.")}}</h3><p>{{tr("Set age and city filters for the letters you read.")}}</p></div><div class="pass-benefits"><div><strong>{{tr("Age range")}}</strong><p>{{tr("Filter letters by author age.")}}</p></div><div><strong>{{tr("City")}}</strong><p>{{tr("Browse letters from a selected city.")}}</p></div></div><p>{{tr("Choose your duration")}}</p><p v-if="active">{{days}} {{tr("days remaining")}} · {{tr("Valid until")}} {{new Date(pass.expiresAt!).toLocaleString()}}</p><p v-else>{{tr(pass.expiresAt?"Your Filter Pass has expired.":"Choose a day pass to unlock age and city filters.")}}</p><div class="pass-plans"><button v-for="p in pass.plans" :key="p.days" class="pass-plan" :data-pass-days="p.days" :aria-pressed="selectedPlan?.days===p.days" :disabled="busy" @click="sheet==='pass-page'?selectedPlan=p:confirmPlan(p)">{{p.days}} {{tr("day")}}{{tr(p.days>1?'s':'')}} <b>◆ {{p.diamonds}}</b></button></div><p>{{tr("One-time payment. No automatic renewal.")}}</p><p>{{tr("Your balance ·")}} {{passBalance}} {{tr("diamonds")}}</p><button id="pass-page-buy" class="primary" :disabled="busy||!selectedPlan" @click="confirmPlan(selectedPlan!)">{{tr(active?"Extend":"Unlock")}} {{tr("Filter Pass")}}</button><p v-if="!pass.plans.length">{{tr("Sign in to view available passes.")}}</p><button class="text-button" @click="sheet='filters'">{{tr("Back to filters")}}</button></template>
<template v-else-if="sheet==='pass-success'"><div class="pass-confirmation"><img :src="asset('01-brand-scenes/diamond')" width="80" alt=""><h3>{{tr(passNotice)}}</h3><p>{{tr("Your balance ·")}} {{passBalance}} {{tr("diamonds")}}</p><p>{{tr("Valid until")}} {{new Date(pass.expiresAt!).toLocaleString()}}</p><button id="pass-done" class="primary" @click="sheet='filters'">{{tr("Done")}}</button></div></template>
<template v-else-if="sheet==='pass-confirm'&&selectedPlan"><div class="pass-confirmation" :aria-busy="busy"><span class="pass-eyebrow">{{tr("Filter Pass")}}</span><div class="pass-payment-symbol"><img :src="asset('01-brand-scenes/diamond')" alt=""></div><h3>{{tr(active?'Extend':'Unlock')}} {{tr("Filter Pass ·")}} {{selectedPlan.days}} {{tr("day")}}{{tr(selectedPlan.days>1?'s':'')}}</h3><p>{{tr("Age and city filters · Valid until")}} {{validUntil}}.<br>{{tr("One-time payment. No automatic renewal.")}}</p><dl class="pass-payment-summary"><div><dt>{{tr("Plan")}}</dt><dd>{{selectedPlan.days}} {{tr("day")}}{{tr(selectedPlan.days>1?'s':'')}}</dd></div><div><dt>{{tr("Price")}}</dt><dd>{{selectedPlan.diamonds}} {{tr("diamonds")}}</dd></div><div><dt>{{tr("Total deduction")}}</dt><dd>◆ {{selectedPlan.diamonds}} {{tr("diamonds")}}</dd></div></dl><p v-if="error" role="alert" class="home-error">{{tr(error)}} {{tr("Your plan and filters are saved. Confirm again to retry.")}}</p><p>{{tr("Your balance ·")}} {{passBalance}} {{tr("diamonds")}}</p><p v-if="passBalance<selectedPlan.diamonds" role="alert">{{tr("Not enough diamonds")}} · {{selectedPlan.diamonds-passBalance}} {{tr("diamonds")}}</p><p v-if="passNotice" role="status">{{tr(passNotice)}}</p><button v-if="passBalance<selectedPlan.diamonds" id="pass-topup" class="primary" @click="passTopup=true">{{tr("Get diamonds")}}</button><button id="confirm-pass-payment" class="primary" :disabled="busy||passBalance<selectedPlan.diamonds" @click="purchase(selectedPlan.days)">{{tr(busy?'Processing…':`Pay ${selectedPlan.diamonds} diamonds`)}}</button><button id="cancel-pass" class="text-button" :disabled="busy" @click="closeSheet">{{tr("Not now · Back to filters")}}</button></div></template>
<template v-else-if="detail"><p class="letter-meta">{{detail.sender.displayName}} · {{detail.sender.city}}</p><p class="letter-content">{{detail.content}}</p></template>
<p v-if="error&&sheet!=='pass-confirm'" role="alert" class="home-error">{{tr(error)}}</p>
</section></div></Transition>
</section>
</Transition>
</template>
<style src="../home.css"></style>

<style scoped src="../HomeFlow.legacy-1.css"></style>

<style scoped src="../HomeFlow.legacy-2.css"></style>
